const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "SkillClaw Research";
pres.title = "SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems";

// Color palette - tech/research focused
const COLORS = {
  darkBg: "0F172A",
  primary: "1E3A8A",
  secondary: "3B82F6",
  accent: "06B6D4",
  lightBg: "F8FAFC",
  cardBg: "FFFFFF",
  textDark: "1E293B",
  textLight: "F1F5F9",
  textMuted: "64748B",
  success: "10B981",
  reject: "EF4444",
  border: "E2E8F0",
};

// ============================================================
// SLIDE 1: Title Slide
// ============================================================
let slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkBg };

// Decorative top accent line
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08,
  fill: { color: COLORS.accent }
});

// Main title
slide1.addText("SkillClaw", {
  x: 0.5, y: 1.4, w: 9, h: 1.0,
  fontSize: 54, fontFace: "Arial Black", color: COLORS.textLight,
  bold: true, align: "center", margin: 0
});

// Subtitle tagline
slide1.addText("Collective Skill Evolution for Multi-User LLM Agent Ecosystems", {
  x: 0.5, y: 2.4, w: 9, h: 0.6,
  fontSize: 22, fontFace: "Arial", color: COLORS.accent,
  align: "center", margin: 0
});

// Divider line
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 3.5, y: 3.2, w: 3, h: 0.02,
  fill: { color: COLORS.secondary }
});

// Source citation
slide1.addText("arxiv.org/abs/2604.08377", {
  x: 0.5, y: 3.5, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial", color: COLORS.textMuted,
  align: "center", margin: 0
});

// Bottom tagline
slide1.addText("Let Skills Evolve Collectively with Agentic Evolver", {
  x: 0.5, y: 4.8, w: 9, h: 0.4,
  fontSize: 16, fontFace: "Arial", color: COLORS.textMuted,
  italic: true, align: "center", margin: 0
});

// ============================================================
// SLIDE 2: Problem - Static Skills
// ============================================================
let slide2 = pres.addSlide();
slide2.background = { color: COLORS.lightBg };

// Header bar
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9,
  fill: { color: COLORS.primary }
});
slide2.addText("Agent Skills Remain Static After Deployment", {
  x: 0.5, y: 0.2, w: 9, h: 0.5,
  fontSize: 26, fontFace: "Arial", color: COLORS.textLight,
  bold: true, margin: 0
});

// Problem statement card
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 9, h: 1.2,
  fill: { color: COLORS.cardBg },
  shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
});
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 0.08, h: 1.2,
  fill: { color: COLORS.reject }
});
slide2.addText("Core Problem", {
  x: 0.75, y: 1.3, w: 8.5, h: 0.35,
  fontSize: 14, fontFace: "Arial", color: COLORS.reject, bold: true, margin: 0
});
slide2.addText("Users manually install skills from a centralized hub. Solutions discovered during interaction rarely persist beyond individual sessions. As similar tasks recur, the same patterns of failure are repeatedly observed — but the system does not improve.", {
  x: 0.75, y: 1.65, w: 8.5, h: 0.65,
  fontSize: 13, fontFace: "Arial", color: COLORS.textDark, margin: 0
});

// Two column comparison
// Left: Static paradigm
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 2.6, w: 4.3, h: 2.5,
  fill: { color: COLORS.cardBg },
  shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
});
slide2.addText("Static Paradigm", {
  x: 0.7, y: 2.75, w: 3.9, h: 0.4,
  fontSize: 16, fontFace: "Arial", color: COLORS.reject, bold: true, margin: 0
});
slide2.addText([
  { text: "Skills installed once, never updated", options: { bullet: true, breakLine: true } },
  { text: "Failures rediscovered per user", options: { bullet: true, breakLine: true } },
  { text: "No knowledge accumulation", options: { bullet: true, breakLine: true } },
  { text: "Memory tied to specific instances", options: { bullet: true } }
], {
  x: 0.7, y: 3.2, w: 3.9, h: 1.7,
  fontSize: 12, fontFace: "Arial", color: COLORS.textDark,
  paraSpaceAfter: 6
});

// Right: SkillClaw paradigm
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 5.2, y: 2.6, w: 4.3, h: 2.5,
  fill: { color: COLORS.cardBg },
  shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
});
slide2.addText("SkillClaw Paradigm", {
  x: 5.4, y: 2.75, w: 3.9, h: 0.4,
  fontSize: 16, fontFace: "Arial", color: COLORS.success, bold: true, margin: 0
});
slide2.addText([
  { text: "Continuous skill evolution from usage", options: { bullet: true, breakLine: true } },
  { text: "Failures become shared improvements", options: { bullet: true, breakLine: true } },
  { text: "System-level knowledge accumulation", options: { bullet: true, breakLine: true } },
  { text: "Cross-user trajectory aggregation", options: { bullet: true } }
], {
  x: 5.4, y: 3.2, w: 3.9, h: 1.7,
  fontSize: 12, fontFace: "Arial", color: COLORS.textDark,
  paraSpaceAfter: 6
});

// ============================================================
// SLIDE 3: Architecture Overview (Closed Loop Diagram)
// ============================================================
let slide3 = pres.addSlide();
slide3.background = { color: COLORS.lightBg };

// Header bar
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9,
  fill: { color: COLORS.primary }
});
slide3.addText("Closed-Loop Pipeline: From Multi-User Interaction to Shared Skill Evolution", {
  x: 0.5, y: 0.2, w: 9, h: 0.5,
  fontSize: 22, fontFace: "Arial", color: COLORS.textLight,
  bold: true, margin: 0
});

// Draw the four-stage closed loop as connected boxes
const boxY = 2.0;
const boxH = 1.4;
const boxW = 1.8;
const stages = [
  { label: "Evidence", desc: "Analyze trajectories\nfor behavioral patterns", color: COLORS.secondary },
  { label: "Attribution", desc: "Diagnose root causes\nof failures & successes", color: COLORS.accent },
  { label: "Evolution", desc: "Propose skill mutations\nthrough open reasoning", color: COLORS.primary },
  { label: "Distribution", desc: "Sync verified skills\nto all agents", color: COLORS.success },
];

const startX = 0.65;
const gap = 0.45;

// Draw connecting arrows (horizontal arrows between boxes)
for (let i = 0; i < 3; i++) {
  const arrowX = startX + boxW + (i * (boxW + gap));
  slide3.addShape(pres.shapes.LINE, {
    x: arrowX, y: boxY + boxH/2,
    w: gap, h: 0,
    line: { color: COLORS.textMuted, width: 2 }
  });
  // Arrow head
  slide3.addText("▶", {
    x: arrowX + gap - 0.15, y: boxY + boxH/2 - 0.15,
    w: 0.3, h: 0.3, fontSize: 10, color: COLORS.textMuted,
    align: "center", valign: "middle", margin: 0
  });
}

// Draw the four stage boxes
stages.forEach((stage, i) => {
  const x = startX + i * (boxW + gap);

  // Box
  slide3.addShape(pres.shapes.RECTANGLE, {
    x: x, y: boxY, w: boxW, h: boxH,
    fill: { color: stage.color },
    shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.15 }
  });

  // Stage label
  slide3.addText(stage.label, {
    x: x, y: boxY + 0.2, w: boxW, h: 0.4,
    fontSize: 15, fontFace: "Arial", color: "FFFFFF",
    bold: true, align: "center", margin: 0
  });

  // Description
  slide3.addText(stage.desc, {
    x: x + 0.1, y: boxY + 0.65, w: boxW - 0.2, h: 0.65,
    fontSize: 10, fontFace: "Arial", color: "FFFFFF",
    align: "center", valign: "top", margin: 0
  });
});

// Top flow: Multi-User Interaction → Session Collection → Agentic Evolver
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.65, y: 1.1, w: 8.7, h: 0.6,
  fill: { color: COLORS.darkBg }
});
slide3.addText("Multi-User Interaction  →  Session Collection  →  Agentic Evolver  →  Skill Synchronization", {
  x: 0.65, y: 1.1, w: 8.7, h: 0.6,
  fontSize: 12, fontFace: "Arial", color: COLORS.textLight,
  align: "center", valign: "middle", margin: 0
});

// Vertical connectors from top flow to stages
const connectorXPositions = [2.05, 3.85, 5.65, 7.45];
connectorXPositions.forEach(cx => {
  slide3.addShape(pres.shapes.LINE, {
    x: cx, y: 1.7, w: 0, h: 0.3,
    line: { color: COLORS.textMuted, width: 1.5, dashType: "dash" }
  });
});

// Bottom note
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.65, y: 3.7, w: 8.7, h: 0.7,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.border, width: 1 }
});
slide3.addText("The evolver performs open-ended agent reasoning over interaction evidence — not predefined update rules. Verified updates merge into shared repository and synchronize to all agents.", {
  x: 0.8, y: 3.75, w: 8.4, h: 0.6,
  fontSize: 11, fontFace: "Arial", color: COLORS.textMuted,
  align: "center", valign: "middle", margin: 0
});

// Compatible systems
slide3.addText("Compatible Systems:", {
  x: 0.65, y: 4.6, w: 2.0, h: 0.35,
  fontSize: 11, fontFace: "Arial", color: COLORS.textMuted, bold: true, margin: 0
});
slide3.addText("OpenClaw  •  CoPaw  •  IronClaw  •  PicoClaw  •  ZeroClaw  •  NanoClaw  •  NemoClaw", {
  x: 2.6, y: 4.6, w: 6.8, h: 0.35,
  fontSize: 11, fontFace: "Arial", color: COLORS.primary, margin: 0
});

// ============================================================
// SLIDE 4: Agentic Evolver Pipeline
// ============================================================
let slide4 = pres.addSlide();
slide4.background = { color: COLORS.lightBg };

// Header bar
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9,
  fill: { color: COLORS.primary }
});
slide4.addText("Agentic Evolver: Evidence → Attribution → Evolution in Three Stages", {
  x: 0.5, y: 0.2, w: 9, h: 0.5,
  fontSize: 24, fontFace: "Arial", color: COLORS.textLight,
  bold: true, margin: 0
});

// Three stage cards
const evolverStages = [
  {
    num: "01",
    title: "Evidence",
    points: [
      "Analyze trajectories from multi-user sessions",
      "Identify behavioral patterns & success signals",
      "Group evidence by skill under diverse contexts"
    ],
    color: COLORS.secondary
  },
  {
    num: "02",
    title: "Attribution",
    points: [
      "Diagnose root causes of failures",
      "Distinguish success patterns from noise",
      "Identify conditions where skill breaks down"
    ],
    color: COLORS.accent
  },
  {
    num: "03",
    title: "Evolution",
    points: [
      "Propose skill mutations via open reasoning",
      "Refine existing skills or create new ones",
      "Submit candidates to validation pipeline"
    ],
    color: COLORS.primary
  }
];

evolverStages.forEach((stage, i) => {
  const cardX = 0.5 + i * 3.1;
  const cardY = 1.2;
  const cardW = 2.9;
  const cardH = 3.8;

  // Card background
  slide4.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: cardY, w: cardW, h: cardH,
    fill: { color: COLORS.cardBg },
    shadow: { type: "outer", blur: 6, offset: 3, angle: 135, color: "000000", opacity: 0.12 }
  });

  // Colored top bar
  slide4.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: cardY, w: cardW, h: 0.12,
    fill: { color: stage.color }
  });

  // Stage number
  slide4.addText(stage.num, {
    x: cardX, y: cardY + 0.25, w: cardW, h: 0.5,
    fontSize: 28, fontFace: "Arial Black", color: stage.color,
    bold: true, align: "center", margin: 0
  });

  // Stage title
  slide4.addText(stage.title, {
    x: cardX, y: cardY + 0.8, w: cardW, h: 0.4,
    fontSize: 18, fontFace: "Arial", color: COLORS.textDark,
    bold: true, align: "center", margin: 0
  });

  // Divider
  slide4.addShape(pres.shapes.RECTANGLE, {
    x: cardX + 0.8, y: cardY + 1.3, w: cardW - 1.6, h: 0.015,
    fill: { color: stage.color, transparency: 50 }
  });

  // Points
  slide4.addText(
    stage.points.map((p, idx) => ({
      text: p,
      options: { bullet: true, breakLine: idx < stage.points.length - 1 }
    })),
    {
      x: cardX + 0.15, y: cardY + 1.45, w: cardW - 0.3, h: 2.2,
      fontSize: 11, fontFace: "Arial", color: COLORS.textDark,
      paraSpaceAfter: 8, valign: "top"
    }
  );
});

// Bottom callout
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 5.15, w: 9, h: 0.35,
  fill: { color: COLORS.primary, transparency: 10 }
});
slide4.addText("Open-ended agent reasoning — not predefined update rules", {
  x: 0.5, y: 5.15, w: 9, h: 0.35,
  fontSize: 12, fontFace: "Arial", color: COLORS.primary,
  italic: true, align: "center", valign: "middle", margin: 0
});

// ============================================================
// SLIDE 5: Cross-User Trajectory Aggregation
// ============================================================
let slide5 = pres.addSlide();
slide5.background = { color: COLORS.lightBg };

// Header bar
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9,
  fill: { color: COLORS.primary }
});
slide5.addText("Cross-User Trajectory Aggregation Exposes Skill Behavioral Boundaries", {
  x: 0.5, y: 0.2, w: 9, h: 0.5,
  fontSize: 22, fontFace: "Arial", color: COLORS.textLight,
  bold: true, margin: 0
});

// Left content area
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.1, w: 5.5, h: 4.2,
  fill: { color: COLORS.cardBg },
  shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
});

slide5.addText("Why Cross-User Aggregation?", {
  x: 0.7, y: 1.25, w: 5.1, h: 0.4,
  fontSize: 16, fontFace: "Arial", color: COLORS.primary, bold: true, margin: 0
});

slide5.addText([
  { text: "Diverse contexts reveal complementary signals", options: { bullet: true, breakLine: true } },
  { text: "Single user rarely generates enough signal to separate generalizable improvements from idiosyncratic fixes", options: { bullet: true, breakLine: true } },
  { text: "Same skill under different users exposes both working conditions and failure modes", options: { bullet: true, breakLine: true } },
  { text: "Trajectories preserve full action–feedback causal chains", options: { bullet: true } }
], {
  x: 0.7, y: 1.7, w: 5.1, h: 2.2,
  fontSize: 12, fontFace: "Arial", color: COLORS.textDark,
  paraSpaceAfter: 10
});

// Key insight box
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 4.0, w: 5.1, h: 1.1,
  fill: { color: COLORS.primary, transparency: 5 },
  line: { color: COLORS.primary, width: 1 }
});
slide5.addText("Key Insight", {
  x: 0.85, y: 4.1, w: 4.8, h: 0.3,
  fontSize: 11, fontFace: "Arial", color: COLORS.primary, bold: true, margin: 0
