slide5.addText("A single user exercising a skill under consistent contexts cannot generate the complementary views needed to identify true behavioral boundaries.", {
  x: 0.85, y: 4.4, w: 4.8, h: 0.6,
  fontSize: 11, fontFace: "Arial", color: COLORS.textMuted, margin: 0
});

