  "OpenClaw", "CoPaw", "IronClaw",
  "PicoClaw", "ZeroClaw", "NanoClaw",
  "NemoClaw"
];

systems.forEach((sys, i) => {
  const row = Math.floor(i / 2);
  const col = i % 2;
  const sysX = 6.2 + col * 1.65;
