slide5.addShape(pres.shapes.RECTANGLE, {
  x: 6.2, y: 3.5, w: 3.3, h: 1.8,
  fill: { color: COLORS.cardBg },
  shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
});
slide5.addText("Evidence Aggregation", {
  x: 6.35, y: 3.6, w: 3.0, h: 0.3,
  fontSize: 11, fontFace: "Arial", color: COLORS.textMuted, bold: true, margin: 0
});

// Mini flow: User sessions → Grouped Evidence
