  x: 6.35, y: 4.0, w: 1.3, h: 0.9,
  fill: { color: COLORS.secondary, transparency: 80 }
});
slide5.addText("User\nSessions", {
  x: 6.35, y: 4.0, w: 1.3, h: 0.9,
  fontSize: 10, fontFace: "Arial", color: COLORS.textDark,
  align: "center", valign: "middle", margin: 0
});
slide5.addText("→", {
  x: 7.65, y: 4.3, w: 0.3, h: 0.3,
  fontSize: 14, color: COLORS.textMuted, align: "center", margin: 0
});
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 7.95, y: 4.0, w: 1.4, h: 0.9,
  fill: { color: COLORS.success, transparency: 80 }
});
slide5.addText("Grouped by\nSkill", {
  x: 7.95, y: 4.0, w: 1.4, h: 0.9,
  fontSize: 10, fontFace: "Arial", color: COLORS.textDark,
  align: "center", valign: "middle", margin: 0
});

// ============================================================
// SLIDE 6: Case Study - Creative Pipeline (1 of 6 accepted)
// ============================================================
let slide6 = pres.addSlide();
slide6.background = { color: COLORS.lightBg };

// Header bar
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9,
  fill: { color: COLORS.primary }
});
slide6.addText("Case Study: Multimodal Creative Pipeline — 6 Days of Evolution", {
  x: 0.5, y: 0.2, w: 9, h: 0.5,
  fontSize: 22, fontFace: "Arial", color: COLORS.textLight,
  bold: true, margin: 0
