const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "SkillClaw Research";
pres.title = "SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems";

// Color palette - tech/research focused
