  darkBg: "0F172A",
  primary: "1E3A8A",
  secondary: "3B82F6",
  accent: "06B6D4",
  lightBg: "F8FAFC",
  cardBg: "FFFFFF",
  textDark: "1E293B",
  textLight: "F1F5F9",
  textMuted: "64748B",
  success: "10B981",
  reject: "EF4444",
  border: "E2E8F0",
};

// ============================================================
// SLIDE 1: Title Slide
// ============================================================
let slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkBg };

// Decorative top accent line
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08,
  fill: { color: COLORS.accent }
});

// Main title
slide1.addText("SkillClaw", {
  x: 0.5, y: 1.4, w: 9, h: 1.0,
  fontSize: 54, fontFace: "Arial Black", color: COLORS.textLight,
  bold: true, align: "center", margin: 0
});

// Subtitle tagline
slide1.addText("Collective Skill Evolution for Multi-User LLM Agent Ecosystems", {
  x: 0.5, y: 2.4, w: 9, h: 0.6,
  fontSize: 22, fontFace: "Arial", color: COLORS.accent,
  align: "center", margin: 0
});

// Divider line
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 3.5, y: 3.2, w: 3, h: 0.02,
  fill: { color: COLORS.secondary }
});

// Source citation
slide1.addText("arxiv.org/abs/2604.08377", {
  x: 0.5, y: 3.5, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial", color: COLORS.textMuted,
  align: "center", margin: 0
});

// Bottom tagline
slide1.addText("Let Skills Evolve Collectively with Agentic Evolver", {
  x: 0.5, y: 4.8, w: 9, h: 0.4,
  fontSize: 16, fontFace: "Arial", color: COLORS.textMuted,
  italic: true, align: "center", margin: 0
});

// ============================================================
// SLIDE 2: Problem - Static Skills
// ============================================================
let slide2 = pres.addSlide();
slide2.background = { color: COLORS.lightBg };

// Header bar
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9,
  fill: { color: COLORS.primary }
});
