  x: 0.5, y: 0.2, w: 9, h: 0.5,
  fontSize: 26, fontFace: "Arial", color: COLORS.textLight,
  bold: true, margin: 0
});

// Problem statement card
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 9, h: 1.2,
  fill: { color: COLORS.cardBg },
  shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
});
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 0.08, h: 1.2,
  fill: { color: COLORS.reject }
});
slide2.addText("Core Problem", {
  x: 0.75, y: 1.3, w: 8.5, h: 0.35,
  fontSize: 14, fontFace: "Arial", color: COLORS.reject, bold: true, margin: 0
});
slide2.addText("Users manually install skills from a centralized hub. Solutions discovered during interaction rarely persist beyond individual sessions. As similar tasks recur, the same patterns of failure are repeatedly observed — but the system does not improve.", {
  x: 0.75, y: 1.65, w: 8.5, h: 0.65,
  fontSize: 13, fontFace: "Arial", color: COLORS.textDark, margin: 0
});

