  fontSize: 11, fontFace: "Arial", color: COLORS.textMuted,
  valign: "middle", margin: 0
});

// ============================================================
// SLIDE 8: Key Takeaways
// ============================================================
let slide8 = pres.addSlide();
slide8.background = { color: COLORS.darkBg };

// Decorative top accent line
slide8.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08,
  fill: { color: COLORS.accent }
});

// Title
slide8.addText("Key Takeaways", {
  x: 0.5, y: 0.4, w: 9, h: 0.6,
  fontSize: 32, fontFace: "Arial Black", color: COLORS.textLight,
  bold: true, align: "center", margin: 0
});

slide8.addText("Three Properties That Distinguish SkillClaw", {
  x: 0.5, y: 0.95, w: 9, h: 0.35,
  fontSize: 16, fontFace: "Arial", color: COLORS.accent,
  align: "center", margin: 0
});

// Three takeaway cards
const takeaways = [
  {
    num: "1",
    title: "Collective Evolution",
    desc: "Individual interactions contribute to a shared, continuously improving skill ecosystem across all users."
  },
  {
    num: "2",
    title: "Fully Automatic",
    desc: "Skill evolution is driven by runtime interaction without manual curation or explicit user intervention."
  },
  {
    num: "3",
    title: "Agentic Evolution Paradigm",
    desc: "Skill updates are produced through open-ended reasoning rather than predefined update rules."
  }
];

takeaways.forEach((tk, i) => {
  const cardX = 0.5 + i * 3.1;
  const cardY = 1.55;
  const cardW = 2.9;
  const cardH = 2.2;

  // Card
  slide8.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: cardY, w: cardW, h: cardH,
    fill: { color: "1E293B" },
    line: { color: COLORS.secondary, width: 1 }
  });

  // Number circle
  slide8.addShape(pres.shapes.OVAL, {
    x: cardX + cardW/2 - 0.3, y: cardY + 0.2, w: 0.6, h: 0.6,
    fill: { color: COLORS.accent }
  });
  slide8.addText(tk.num, {
    x: cardX + cardW/2 - 0.3, y: cardY + 0.2, w: 0.6, h: 0.6,
    fontSize: 18, fontFace: "Arial Black", color: COLORS.darkBg,
    bold: true, align: "center", valign: "middle", margin: 0
  });

  // Title
  slide8.addText(tk.title, {
    x: cardX + 0.15, y: cardY + 0.9, w: cardW - 0.3, h: 0.4,
    fontSize: 14, fontFace: "Arial", color: COLORS.textLight,
    bold: true, align: "center", margin: 0
  });

  // Description
  slide8.addText(tk.desc, {
    x: cardX + 0.15, y: cardY + 1.3, w: cardW - 0.3, h: 0.8,
    fontSize: 10, fontFace: "Arial", color: COLORS.textMuted,
    align: "center", valign: "top", margin: 0
  });
});

// Implications section
slide8.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.95, w: 9, h: 0.02,
  fill: { color: COLORS.secondary, transparency: 50 }
});

slide8.addText("Implications for Continuously Improving Agent Systems", {
  x: 0.5, y: 4.15, w: 9, h: 0.35,
  fontSize: 14, fontFace: "Arial", color: COLORS.secondary,
  bold: true, align: "center", margin: 0
});

slide8.addText("SkillClaw enables LLM agent ecosystems to transform runtime failures into cumulative improvements — shifting from static skill libraries to self-improving, collectively-evolving systems.", {
  x: 0.5, y: 4.55, w: 9, h: 0.5,
  fontSize: 12, fontFace: "Arial", color: COLORS.textMuted,
  align: "center", margin: 0
});

// Evaluation note
slide8.addText("Evaluated on WildClawBench with Qwen3-Max backbone", {
  x: 0.5, y: 5.2, w: 9, h: 0.3,
  fontSize: 11, fontFace: "Arial", color: COLORS.textMuted,
  italic: true, align: "center", margin: 0
});

// Write the file
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Presentation created successfully: /app/output/final_deck.pptx"))
  .catch(err => console.error("Error creating presentation:", err));

